      "path": "package.json",
      "content": "{\n  \"name\": \"dsh-session-diff\",\n  \"version\": \"0.1.0\",\n  \"description\": \"Session-scoped diff view for the DSH Web right sidebar: open a file the current conversation changed and it renders in place with git-style added/removed line backgrounds, +/− markers and dual old/new line numbers under syntax colouring, a Changes only / Whole file toggle, a Re-read button, and a companion tab listing every file the session changed.\",\n  \"type\": \"module\",\n  \"main\": \"lib/index.js\",\n  \"exports\": {\n    \".\": {\n      \"default\": \"./lib/index.js\"\n    },\n    \"./client\": {\n      \"default\": \"./lib/client.js\"\n    },\n    \"./cordis.patch.yml\": \"./cordis.patch.yml\",\n    \"./package.json\": \"./package.json\"\n  },\n  \"files\": [\n    \"lib\",\n    \"src\",\n    \"scripts\",\n    \"cordis.patch.yml\",\n    \"README.md\",\n    \"LICENSE\"\n  ],\n  \"keywords\": [\n    \"dsh\",\n    \"deepseek-harness\",\n    \"plugin\",\n    \"diff\",\n    \"sidebar\",\n    \"code-review\"\n  ],\n  \"engines\": {\n    \"node\": \">=18\"\n  },\n  \"repository\": {\n    \"type\": \"git\",\n    \"url\": \"git+https://github.com/2002XiaoYu/dsh-session-diff.git\"\n  },\n  \"homepage\": \"https://github.com/2002XiaoYu/dsh-session-diff#readme\",\n  \"bugs\": {\n    \"url\": \"https://github.com/2002XiaoYu/dsh-session-diff/issues\"\n  },\n  \"dsh\": {\n    \"bundle\": {\n      \"patch\": \"./cordis.patch.yml\"\n    },\n    \"client\": {\n      \"platform\": \"web\",\n      \"inject\": [\n        \"@deepseek-ai/dsh-client-locale\",\n        \"@deepseek-ai/dsh-api-remotes\",\n        \"@deepseek-ai/dsh-api-workspace-files\",\n        \"@deepseek-ai/dsh-api-session-controller\",\n        \"@deepseek-ai/dsh-client-ui-sidebar-right\",\n        \"@deepseek-ai/dsh-client-ui-chat\",\n        \"@deepseek-ai/dsh-client-ui-conversation\"\n      ]\n    }\n  },\n  \"scripts\": {\n    \"build\": \"node scripts/build.mjs\",\n    \"prepack\": \"node scripts/build.mjs\",\n    \"test\": \"node test/logic.test.mjs && node test/plugin.smoke.mjs\"\n  },\n  \"license\": \"MIT\",\n  \"devDependencies\": {\n    \"diff\": \"^5.2.2\",\n    \"react\": \"^18.3.1\",\n    \"react-dom\": \"^18.3.1\"\n  }\n}\n"
